select count(*), sum(customer.c_custkey) from customer join (select c_custkey as id from customer c2 where exists (select 1 from orders where o_custkey = c2.c_custkey and o_totalprice > 400000) %F) x on customer.c_custkey = x.id join (select c_custkey as id from customer c3 where exists (select 1 from orders where o_custkey = c3.c_custkey and o_orderpriority = '1-URGENT') %F) y on customer.c_custkey = y.id;
select count(*), sum(k) from (select c_custkey as k, upper(c_name) as u from customer where not exists (select 1 from orders where o_custkey = c_custkey) %F) s where u like 'CUSTOMER#0000%';
select count(*), sum(k) from (select c_custkey as k from customer where c_nationkey in (select n_nationkey from nation where n_regionkey = 1) %F) s, nation where s.k = n_nationkey + 1;
select count(*) from (select c_custkey as k from customer where c_nationkey not in (select n_nationkey from nation where n_regionkey = 1) %F) s;
select count(*), max(k) from (select c_custkey as k, length(c_phone) as l from customer where c_acctbal > (select avg(c_acctbal) from customer) %F) s where l = 15;
select cc, count(*) from (select substr(c_phone, 1, 2) as cc from customer where exists (select 1 from orders where o_custkey = c_custkey and o_orderstatus = 'F') and not exists (select 1 from orders o2 where o2.o_custkey = c_custkey and o2.o_orderstatus = 'O') %F) s group by cc order by cc limit 5;
